  bool _buttonLockTor = false;
  Future<void> onTorTapped() async {
    if (_buttonLockTor) {
      return;
    }
    _buttonLockTor = true;
    try {
      if (ref.read(prefsChangeNotifierProvider).useTor) {
        await disconnectTor(ref, context);
      } else {
        await connectTor(ref, context);
      }
    } catch (_) {
      // Nothing. Just using finally to ensure button lock is reset in case
      // some unexpected error happens
    } finally {
      _buttonLockTor = false;
    }
  }

  Future<void> _attemptRescan() async {
    if (!Platform.isLinux) await WakelockPlus.enable();

    try {
      if (mounted) {
        unawaited(
          showDialog<dynamic>(
            context: context,
            useSafeArea: false,
            barrierDismissible: false,
            builder: (context) => RescanningDialog(walletId: widget.walletId),
          ),
        );

        try {
          final wallet = ref.read(pWallets).getWallet(widget.walletId);

          await wallet.recover(isRescan: true);

          if (mounted) {
            // pop rescanning dialog
            Navigator.of(context, rootNavigator: isDesktop).pop();

            final message = l10n.netRescanCompleted;

            // show success
            await showDialog<dynamic>(
              context: context,
              useSafeArea: false,
              barrierDismissible: true,
              builder: (context) => ConditionalParent(
                condition: isDesktop,
                builder: (child) =>
                    DesktopDialog(maxHeight: 150, maxWidth: 500, child: child),
                child: StackDialog(
                  title: message,
                  rightButton: TextButton(
                    style: Theme.of(context)
                        .extension<StackColors>()!
                        .getSecondaryEnabledButtonStyle(context),
                    child: Text(
                      l10n.commonOk,
                      style: STextStyles.itemSubtitle12(context),
                    ),
                    onPressed: () {
                      Navigator.of(context, rootNavigator: isDesktop).pop();
                    },
                  ),
                ),
              ),
            );
          }
        } catch (e) {
          if (!Platform.isLinux) await WakelockPlus.disable();

          if (mounted) {
            // pop rescanning dialog
            Navigator.of(context, rootNavigator: isDesktop).pop();

            // show error
            await showDialog<dynamic>(
              context: context,
              useSafeArea: false,
              barrierDismissible: true,
              builder: (context) => StackDialog(
                title: l10n.netRescanFailed,
                message: e.toString(),
                rightButton: TextButton(
                  style: Theme.of(context)
                      .extension<StackColors>()!
                      .getSecondaryEnabledButtonStyle(context),
                  child: Text(
                    l10n.commonOk,
                    style: STextStyles.itemSubtitle12(context),
                  ),
                  onPressed: () {
                    Navigator.of(context, rootNavigator: isDesktop).pop();
                  },
                ),
              ),
            );
          }
        }
      }
    } finally {
      if (!Platform.isLinux) await WakelockPlus.disable();
    }
  }

  String _percentString(double value) {
    final double realPercent = (value * 10000).ceil().clamp(0, 10000) / 100.0;
    if (realPercent > 99.99 && _currentSyncStatus == WalletSyncStatus.syncing) {
      return Format.percent(99.99);
    }
    return Format.percent(realPercent);
  }

  @override
  void initState() {
    isDesktop = Util.isDesktop;
    _currentSyncStatus = widget.initialSyncStatus;
    if (_currentSyncStatus == WalletSyncStatus.synced) {
      _percent = 1;
    } else {
      _percent = 0;
    }

    eventBus = widget.eventBus != null
        ? widget.eventBus!
        : GlobalEventBus.instance;

    _syncStatusSubscription = eventBus
        .on<WalletSyncStatusChangedEvent>()
        .listen((event) async {
          if (event.walletId == widget.walletId) {
            setState(() {
              _currentSyncStatus = event.newStatus;
            });
          }
        });

    _refreshSubscription = eventBus.on<RefreshPercentChangedEvent>().listen((
      event,
    ) async {
      if (event.walletId == widget.walletId) {
        setState(() {
          _percent = event.percent.clamp(0.0, 1.0);
        });
      }
    });

