    //       }
    //       setState(() {
    //         _currentNodeStatus = event.newStatus;
    //       });
    //     }
    //   },
    // );

    // Initialize the TorConnectionStatus.
    _torConnectionStatus = ref.read(pTorService).status;

    super.initState();
  }

  @override
  void dispose() {
    _syncStatusSubscription.cancel();
    _refreshSubscription.cancel();
    super.dispose();
  }

