                  children: [
                    Row(
                      children: [
                        Container(
                          width: _iconSize,
                          height: _iconSize,
                          decoration: BoxDecoration(
                            color: Theme.of(context)
                                .extension<StackColors>()!
                                .textFieldDefaultBG,
                            borderRadius: BorderRadius.circular(_iconSize),
