                            ),
                          ],
                        ),
                      ],
                    ),
                    SvgPicture.asset(
                      _advancedIsExpanded
                          ? Assets.svg.chevronUp
                          : Assets.svg.chevronDown,
                      width: 12,
                      height: 6,
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .textSubtitle1,
                    ),
                  ],
                ),
                body: Row(
                  children: [
                    Padding(
                      padding: const EdgeInsets.only(
                        left: 50,
                        top: 16,
                        bottom: 6,
                      ),
                      child: CustomTextButton(
                        text: l10n.netRescan,
                        onTap: () async {
                          await Navigator.of(context).push(
                            FadePageRoute<void>(
